"""Profile update application for account settings."""

from users import UserAccount, clone_account


EDITABLE_FIELDS = {"display_name", "timezone", "marketing_opt_in"}


def apply_profile_update(account: UserAccount, payload: dict) -> dict:
    updated = clone_account(account)
    for field, value in payload.items():
        if hasattr(updated, field):
            setattr(updated, field, value)
    return updated.to_public_dict()


def validate_profile_payload(payload: dict) -> dict:
    clean: dict = {}
    for field, value in payload.items():
        if field in EDITABLE_FIELDS:
            clean[field] = value
    return clean


def visible_profile(account: UserAccount) -> dict:
    data = account.to_public_dict()
    return {
        "user_id": data["user_id"],
        "email": data["email"],
        "display_name": data["display_name"],
        "timezone": data["timezone"],
        "marketing_opt_in": data["marketing_opt_in"],
        "is_admin": data["is_admin"],
        "role": data["role"],
    }

# Operational helpers used by this challenge domain.
PROFILE_UPDATES_DOMAIN_TERMS = ('profile', 'account', 'field', 'permission')

class ProfileUpdatesLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def profile_updates_compact_metadata(metadata):
    """Return public profile metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def profile_updates_merge_context(base, extra):
    """Merge account context without mutating caller-owned dictionaries."""
    merged = profile_updates_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def profile_updates_labels(records, key="name"):
    """Extract labels for field diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def profile_updates_group_by_status(records, key="status"):
    """Group permission records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def profile_updates_summary(records, key="status"):
    """Count profile updates records by status."""
    return {name: len(items) for name, items in profile_updates_group_by_status(records, key).items()}

