from profile_updates import apply_profile_update, validate_profile_payload
from users import UserAccount


def test_display_name_can_be_updated():
    account = UserAccount("u1", "a@example.com", "Old")
    assert apply_profile_update(account, {"display_name": "New"})["display_name"] == "New"


def test_admin_flag_cannot_be_set_by_profile_payload():
    account = UserAccount("u1", "a@example.com", "Old", is_admin=False)
    assert apply_profile_update(account, {"is_admin": True})["is_admin"] is False


def test_role_cannot_be_changed_by_profile_payload():
    account = UserAccount("u1", "a@example.com", "Old", role="member")
    assert apply_profile_update(account, {"role": "admin"})["role"] == "member"


def test_allowed_marketing_flag_still_updates():
    account = UserAccount("u1", "a@example.com", "Old")
    assert apply_profile_update(account, {"marketing_opt_in": True})["marketing_opt_in"] is True


def test_validator_drops_uneditable_fields():
    assert validate_profile_payload({"timezone": "AEST", "is_admin": True}) == {"timezone": "AEST"}
